const r = $input.first().json.body || $input.first().json;
const score = r.score || 0;
const temp = r.temperature || 'cold';

return [{ json: {
  score,
  temperature: temp,
  tags: r.tags || [],
  service: r.qualification?.service_needed || '',
  budget: r.qualification?.budget_range || '',
  timeline: r.qualification?.timeline || '',
  package: r.recommendedPackage || '',
  nextStep: r.nextStep || '',
  leadName: r.lead?.name || '',
  leadEmail: r.lead?.email || '',
  response: r.fullOutput || '',
} }];
